/* @author MILO-GAO(高振銘)@2020 */ package page2020.view.bs4;import page2020.view.html5.H5a;import page2020.view.html5.H5img;import page2020.view.html5.H5p;import page2020.view.html5.H5text;public class B4card extends B4boxes<B4card> {	public static final String card = "card";	public static final String header = "card-header";	public static final String body = "card-body";	public static final String footer = "card-footer";	public static final String title = "card-title";	public static final String subtitle = "card-subtitle";	public static final String text = "card-text";	public static final String link = "card-link";	public static final String tabs = "card-header-tabs";	public static final String pills = "card-header-pills";	public static final String imgTop = "card-img-top";	public static final String imgOverlay = "card-img-overlay";	public static final String imgBottom = "card-img-bottom";	public static final String stretch = "stretched-link";	public static final String group = "card-group";	public static final String columns = "card-columns";	public static final String deck = "card-deck";	public static B4element group() {		return new B4element().cssClass(group);	}	public static B4element columns() {		return new B4element().cssClass(columns);	}	public static B4element deck() {		return new B4element().cssClass(deck);	}	public B4card() {		super.data(PageKey.type, "card");		super.cssClass(card);	}	public B4card header() {		super.box("div", header);		return this;	}	public B4card body() {		super.box("div", body);		return this;	}	public B4card footer() {		super.box("div", footer);		return this;	}	public B4card tabs(B4nav nav) {				super.box("div", header).append(nav.boxes().cssClass(tabs));		return this;	}	public B4card pills(B4nav nav) {		super.box("div", header).append(nav.boxes().cssClass(pills));		return this;	}	public B4card title(H5text element) {		super.append(element.cssClass(title));		return this;	}	public B4card subtitle(H5text element) {		super.append(element.cssClass(subtitle));		return this;	}	public B4card p(H5p p) {		super.append(p.cssClass(text));		return this;	}	public B4card link(H5a a) {		super.append(a.cssClass(link));		return this;	}	public B4card link(boolean stretchLink, H5a a) {		if (stretchLink) {			a.cssClass(stretch);		}		return link(a);	}	public B4card image(H5img img) {		return super.boxes().append(img.cssClass(imgTop));	}	public B4card image(boolean bottom, H5img img) {		return super.boxes().append(img.cssClass(bottom ? imgBottom : imgTop));	}	public B4card overlay() {		super.box(new B4element().cssClass(imgOverlay));		return this;	}	}